import re

_NUMBER_RE = re.compile(r"^-?\d+$")


class StackUnderflowError(Exception):
    pass


def _check(stack, n):
    if len(stack) < n:
        raise StackUnderflowError("Insufficient number of items in stack")


def _binary(stack, fn):
    _check(stack, 2)
    b = stack.pop()
    a = stack.pop()
    stack.append(fn(a, b))


def _plus(stack):
    _binary(stack, lambda a, b: a + b)


def _minus(stack):
    _binary(stack, lambda a, b: a - b)


def _mul(stack):
    _binary(stack, lambda a, b: a * b)


def _div(stack):
    _check(stack, 2)
    b = stack.pop()
    a = stack.pop()
    if b == 0:
        raise ZeroDivisionError("divide by zero")
    q = abs(a) // abs(b)
    if (a < 0) != (b < 0):
        q = -q
    stack.append(q)


def _dup(stack):
    _check(stack, 1)
    stack.append(stack[-1])


def _drop(stack):
    _check(stack, 1)
    stack.pop()


def _swap(stack):
    _check(stack, 2)
    stack[-1], stack[-2] = stack[-2], stack[-1]


def _over(stack):
    _check(stack, 2)
    stack.append(stack[-2])


_BUILTINS = {
    "+": [_plus],
    "-": [_minus],
    "*": [_mul],
    "/": [_div],
    "dup": [_dup],
    "drop": [_drop],
    "swap": [_swap],
    "over": [_over],
}


def _is_number(token):
    return bool(_NUMBER_RE.match(token))


def _compile(tokens, words):
    """Compile tokens into a flat body of ints and operations.

    Word references are resolved at definition time, so a word always
    captures the definitions that existed when it was defined.
    """
    body = []
    for token in tokens:
        if _is_number(token):
            body.append(int(token))
        else:
            key = token.lower()
            if key not in words:
                raise ValueError("undefined operation")
            body.extend(words[key])
    return body


def _execute(body, stack):
    for item in body:
        if isinstance(item, int):
            stack.append(item)
        else:
            item(stack)


def evaluate(input_data):
    stack = []
    words = dict(_BUILTINS)
    for line in input_data:
        tokens = line.split()
        i = 0
        while i < len(tokens):
            if tokens[i] == ":":
                if i + 1 >= len(tokens):
                    raise ValueError("illegal operation")
                name = tokens[i + 1]
                if _is_number(name):
                    raise ValueError("illegal operation")
                try:
                    end = tokens.index(";", i + 2)
                    rest = tokens[end + 1:]
                except ValueError:
                    end = len(tokens)
                    rest = []
                words[name.lower()] = _compile(tokens[i + 2:end], words)
                tokens = rest
                i = 0
            else:
                token = tokens[i]
                if _is_number(token):
                    stack.append(int(token))
                else:
                    key = token.lower()
                    if key not in words:
                        raise ValueError("undefined operation")
                    _execute(words[key], stack)
                i += 1
    return stack

